class IndependentSmaAndRsiStrategies(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        self.symbols = [self.AddEquity(ticker, Resolution.Daily).Symbol for ticker in tickers]

        self.spy = self.Symbol("SPY")
        self.aapl = self.Symbol("AAPL")

        self.spy_closes = RollingWindow[float](101)
        self.aapl_previous_close = None
        self.aapl_red_streak = 0
        self.aapl_rsi = self.RSI(self.aapl, 14, MovingAverageType.Wilders, Resolution.Daily)

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0
        self.strategy_a_pending = False
        self.strategy_b_pending = False
        self.order_slots = {}

    def OnData(self, data: Slice):
        # Market-state quantities continue updating whenever their own data exists.
        if data.Bars.ContainsKey(self.spy):
            self.spy_closes.Add(float(data.Bars[self.spy].Close))

        if data.Bars.ContainsKey(self.aapl):
            close = float(data.Bars[self.aapl].Close)
            if self.aapl_previous_close is not None:
                if close < self.aapl_previous_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.aapl_previous_close = close

        # Skip all rule evaluation unless every subscribed ticker has today's bar.
        if not all(data.Bars.ContainsKey(symbol) for symbol in self.symbols):
            return

        # No trading until every indicator or rolling window used by a rule is ready.
        if not self.spy_closes.IsReady or not self.aapl_rsi.IsReady:
            return

        spy_close = float(data.Bars[self.spy].Close)
        aapl_close = float(data.Bars[self.aapl].Close)

        current_sma = sum(self.spy_closes[i] for i in range(100)) / 100.0
        previous_sma = sum(self.spy_closes[i] for i in range(1, 101)) / 100.0
        previous_spy_close = self.spy_closes[1]

        upward_sma_cross = (
            previous_spy_close <= previous_sma and spy_close > current_sma
        )
        downward_sma_cross = (
            previous_spy_close >= previous_sma and spy_close < current_sma
        )

        # Evaluate all sells before any buys.
        if (
            self.strategy_a_lot > 0
            and not self.strategy_a_pending
            and downward_sma_cross
        ):
            self._submit_for_slot("A", self.spy, -self.strategy_a_lot)

        if (
            self.strategy_b_lot > 0
            and not self.strategy_b_pending
            and self.aapl_rsi.Current.Value > 60
        ):
            self._submit_for_slot("B", self.aapl, -self.strategy_b_lot)

        if (
            self.strategy_a_lot == 0
            and not self.strategy_a_pending
            and upward_sma_cross
        ):
            quantity = int((float(self.Portfolio.TotalPortfolioValue) * 0.40) / spy_close)
            if quantity > 0:
                self._submit_for_slot("A", self.spy, quantity)

        if (
            self.strategy_b_lot == 0
            and not self.strategy_b_pending
            and self.aapl_red_streak >= 3
            and float(self.Portfolio.Cash) >= 20_000
        ):
            quantity = int(20_000 / aapl_close)
            if quantity > 0:
                self._submit_for_slot("B", self.aapl, quantity)

    def _submit_for_slot(self, slot, symbol, quantity):
        ticket = self.MarketOrder(symbol, quantity)
        self.order_slots[ticket.OrderId] = slot
        if slot == "A":
            self.strategy_a_pending = True
        else:
            self.strategy_b_pending = True

    def OnOrderEvent(self, order_event):
        slot = self.order_slots.get(order_event.OrderId)
        if slot is None:
            return

        if order_event.Status == OrderStatus.PartiallyFilled or order_event.Status == OrderStatus.Filled:
            if slot == "A":
                self.strategy_a_lot += int(order_event.FillQuantity)
            else:
                self.strategy_b_lot += int(order_event.FillQuantity)

        if order_event.Status in [OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid]:
            if slot == "A":
                self.strategy_a_pending = False
            else:
                self.strategy_b_pending = False
            del self.order_slots[order_event.OrderId]
