            if data.Bars.ContainsKey(symbol):
                bars[ticker] = data.Bars[symbol]

        # Market-state quantities continue updating for every bar that is present.
        for ticker, bar in bars.items():
            close = float(bar.Close)
            previous_close = self.previous_closes[ticker]

            if previous_close is not None and close < previous_close:
                self.red_streaks[ticker] += 1
            else:
                self.red_streaks[ticker] = 0

            self.previous_closes[ticker] = close
            self.close_windows[ticker].Add(close)

            if ticker == "AAPL":
                self.aapl_rsi.Update(IndicatorDataPoint(bar.EndTime, close))

        # Skip all rule evaluation if any subscribed ticker lacks today's bar.
        if len(bars) != len(self.tickers):
            return

        # Do not trade until every rule input is fully formed.
        if (self.close_windows["SPY"].Count < 101 or
                self.close_windows["AAPL"].Count < 4 or
                not self.aapl_rsi.IsReady):
            return

        spy_window = self.close_windows["SPY"]
